import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositVal, uint160 extraKey) public {
        // Bound deposit to a large range that may still trigger overflow
        depositVal = bound(depositVal, 1, type(uint256).max);
        // Ensure the second depositor is distinct from the first
        address actor2 = address(uint160(bytes20(bytes20(keccak256(abi.encodePacked(extraKey))))));
        vm.assume(actor2 != address(this) && actor2 != address(0));

        // First deposit: this contract deposits an initial balance to establish a baseline
        vm.deal(address(this), depositVal);
        c.deposit{value: depositVal}();

        // Second deposit: fuzzed actor2 deposits the same large amount, potentially overflowing their balance
        vm.deal(actor2, depositVal);
        vm.prank(actor2);
        c.deposit{value: depositVal}();

        // Sum all stored balances (only non-zero ones we know of)
        uint256 sum = 0;
        // We cannot iterate over mapping keys, so we sum the two known depositors
        // and assert on the relation observable from outside.
        uint256 bal1 = c.balances(address(this));
        uint256 bal2 = c.balances(actor2);
        unchecked { sum = bal1 + bal2; }

        // The contract's total ETH balance cannot be less than the sum of recorded balances.
        // Under overflow in the buggy version, bal2 wraps, making sum exceed address(c).balance.
        assertTrue(address(c).balance >= sum, "Contract balance is less than sum of balances (overflow)");
    }
}

