import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address actor) public {
        // Restrict to admissible domain
        vm.assume(actor != address(0));
        vm.assume(depositAmount > 0);
        vm.assume(withdrawAmount > 0);
        vm.assume(withdrawAmount <= depositAmount);
        vm.assume(actor != c.creator());

        // Fund actor and deposit
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        // Record state before withdraw
        uint256 balanceBefore = c.balances(actor);
        uint256 contractBalanceBefore = address(c).balance;

        // Perform withdraw
        vm.prank(actor);
        c.withdraw(withdrawAmount);

        uint256 contractBalanceAfter = address(c).balance;
        uint256 balanceAfter = c.balances(actor);

        // The invariant: the balance of the actor after withdraw must reflect the deduction.
        // In the correct contract, balanceAfter == balanceBefore - withdrawAmount.
        // In the buggy contract, balanceAfter == balanceBefore (deduction removed).
        // If the balance was correctly reduced, the sum of all known balances should equal the contract balance
        // (ignoring the creator's initial 0 balance). Here we use a direct invariant:
        // The actor's balance after withdrawal plus the amount they withdrew equals the actor's balance before withdrawal.
        assertTrue(balanceAfter + withdrawAmount == balanceBefore);
    }
}

